nta.declaration:
////////////////////////////////////////////////////////////////
//                     Global Declarations                     //
////////////////////////////////////////////////////////////////

// --- Types for 3 Circles and 3 Squares ----------------------
typedef int[0,2] circle_id_t
typedef int[0,2] square_id_t

// --- Enemy Parameters (Vanilla version) ---------------------
const int CIRCLE_SPEED   = 1
const int CIRCLE_HEALTH  = 10
const int CIRCLE_DAMAGE  = 2
const int SQUARE_SPEED   = 3
const int SQUARE_HEALTH  = 20
const int SQUARE_DAMAGE  = 4

// --- Turret Parameters (Vanilla + Turrets) ------------------
const int BASIC_RANGE       = 2
const int BASIC_FIRE_SPEED  = 2
const int BASIC_DAMAGE      = 2
const int CANNON_RANGE      = 1
const int CANNON_FIRE_SPEED = 7
const int CANNON_DAMAGE     = 5
const int SNIPER_RANGE      = 4
const int SNIPER_FIRE_SPEED = 20
const int SNIPER_DAMAGE     = 8

// --- Main Tower Health --------------------------------------
const int MAIN_TOWER_HEALTH = 10

// --- Map Path Data ------------------------------------------
// We model a single contiguous path of length 23, plus two alternate sub‐paths.
typedef struct { int x; int y; } Coord

const int PATH_LENGTH = 23
const Coord path[PATH_LENGTH] = {
  {0,0}, {1,0}, {2,0}, {3,0}, {4,0},
  {4,1}, {4,2}, {4,3}, {4,4}, {5,4},
  {6,4}, {7,4}, {8,4}, {8,5}, {8,6},
  {8,7}, {9,7}, {10,7}, {11,7}, {12,7},
  {13,7}, {14,7}, {15,4}
}

const int ALT_PATH1_LENGTH = 10
const Coord alt_path1[ALT_PATH1_LENGTH] = {
  {7,3}, {7,2}, {7,1}, {8,1}, {9,1},
  {10,1}, {11,1}, {12,1}, {13,1}, {14,1}
}

const int ALT_PATH2_LENGTH = 5
const Coord alt_path2[ALT_PATH2_LENGTH] = {
  {10,6}, {10,5}, {11,5}, {12,5}, {13,5}
}

// --- Branch Indices on the Main Path ------------------------
// Index 11 corresponds to (7,4); Index 17 corresponds to (10,7)
const int BRANCH_INDEX1 = 11
const int BRANCH_INDEX2 = 17

// --- Arrays for 3 Circles ------------------------------------
int pos_circle[circle_id_t]        = {0,  0,  0}
int hp_circle[circle_id_t]         = {CIRCLE_HEALTH, CIRCLE_HEALTH, CIRCLE_HEALTH}
int dmg_circle[circle_id_t]        = {CIRCLE_DAMAGE, CIRCLE_DAMAGE, CIRCLE_DAMAGE}
int spawn_circle[circle_id_t]      = {0,  2,  4}
int time_circle[circle_id_t]       = {0,  0,  0}
int path_choice_circle[circle_id_t] = {0, 0, 0}
int alt_pos_circle[circle_id_t]     = {0, 0, 0}

// --- Arrays for 3 Squares ------------------------------------
int pos_square[square_id_t]        = {0,  0,  0}
int hp_square[square_id_t]         = {SQUARE_HEALTH, SQUARE_HEALTH, SQUARE_HEALTH}
int dmg_square[square_id_t]        = {SQUARE_DAMAGE, SQUARE_DAMAGE, SQUARE_DAMAGE}
int spawn_square[square_id_t]      = {0,  3,  6}
int time_square[square_id_t]       = {0,  0,  0}
int path_choice_square[square_id_t] = {0, 0, 0}
int alt_pos_square[square_id_t]     = {0, 0, 0}

// --- Game State ----------------------------------------------
int lives = MAIN_TOWER_HEALTH
bool game_over = false

// --- Global Clock (integer) ----------------------------------
int global_clock = 0

// --- Enable or disable branching at path nodes (to cut down state‐space) ---
const bool allow_branching = false

// --- Distance helper -----------------------------------------
int distance(int x1, int y1, int x2, int y2) {
  return abs(x1 - x2) + abs(y1 - y2)
}

// --- Check if a given circle has reached the end of its chosen path ---
bool reached_end_circle(circle_id_t id) {
  if (path_choice_circle[id] == 0) {
    return pos_circle[id] >= PATH_LENGTH - 1
  } else if (path_choice_circle[id] == 1) {
    return alt_pos_circle[id] >= ALT_PATH1_LENGTH - 1
  } else {
    return alt_pos_circle[id] >= ALT_PATH2_LENGTH - 1
  }
}

// --- Check if a given square has reached the end of its chosen path ---
bool reached_end_square(square_id_t id) {
  if (path_choice_square[id] == 0) {
    return pos_square[id] >= PATH_LENGTH - 1
  } else if (path_choice_square[id] == 1) {
    return alt_pos_square[id] >= ALT_PATH1_LENGTH - 1
  } else {
    return alt_pos_square[id] >= ALT_PATH2_LENGTH - 1
  }
}

// --- Are all enemies (circles & squares) either done or not on‐map? ---
bool all_enemies_gone() {
  int i
  for (i = 0; i < 3; i++) {
    if (
      (path_choice_circle[i] == 0 && pos_circle[i] >= 0 && pos_circle[i] < PATH_LENGTH)
      || (path_choice_circle[i] == 1 && alt_pos_circle[i] >= 0 && alt_pos_circle[i] < ALT_PATH1_LENGTH)
      || (path_choice_circle[i] == 2 && alt_pos_circle[i] >= 0 && alt_pos_circle[i] < ALT_PATH2_LENGTH)
    ) {
      return false
    }
  }
  for (i = 0; i < 3; i++) {
    if (
      (path_choice_square[i] == 0 && pos_square[i] >= 0 && pos_square[i] < PATH_LENGTH)
      || (path_choice_square[i] == 1 && alt_pos_square[i] >= 0 && alt_pos_square[i] < ALT_PATH1_LENGTH)
      || (path_choice_square[i] == 2 && alt_pos_square[i] >= 0 && alt_pos_square[i] < ALT_PATH2_LENGTH)
    ) {
      return false
    }
  }
  return true
}

// --- Mark a circle as “done” by setting its pos or alt_pos to –1 ---
void mark_circle_done(circle_id_t id) {
  if (path_choice_circle[id] == 0) {
    pos_circle[id] = -1
  } else {
    alt_pos_circle[id] = -1
  }
}

// --- Mark a square as “done” by setting its pos or alt_pos to –1 ---
void mark_square_done(square_id_t id) {
  if (path_choice_square[id] == 0) {
    pos_square[id] = -1
  } else {
    alt_pos_square[id] = -1
  }
}
